// Domain 3 — Wireless monitoring and protection flashcards.
export default [
  { id: 'd3-f001', topic: '3.1', front: 'Rogue AP vs neighbouring AP?', back: 'A **rogue** is an unmanaged AP connected to your wired network. A neighbour is only on the air (interference, no path into your LAN).' },
  { id: 'd3-f002', topic: '3.1', front: 'Two on-wire rogue detection methods?', back: '**Exact MAC address match** (same MAC on air and LAN; non-NAT rogues) and **MAC adjacency** (wireless MAC close to a wired MAC; NAT routers).' },
  { id: 'd3-f003', topic: '3.1', front: 'MAC adjacency setting and default?', back: '`config wireless-controller global` → `set rogue-scan-mac-adjacency` (0–31, default **7**).' },
  { id: 'd3-f004', topic: '3.1', front: 'Main limitation of on-wire detection?', back: 'At least one client must be associated to the suspect AP and sending traffic; for NAT routers the wireless and wired MACs must be close.' },
  { id: 'd3-f005', topic: '3.1', front: 'Rogue AP monitor states?', back: 'Unclassified (initial), Accepted, Rogue, Suppressed Rogue AP. Path: Dashboard > WiFi > Rogue APs.' },
  { id: 'd3-f006', topic: '3.1', front: 'WIDS profile switch that turns on rogue AP detection?', back: '`set ap-scan enable` (default disable), plus a `sensor-mode` of `foreign` or `both`.' },
  { id: 'd3-f007', topic: '3.1', front: '`sensor-mode foreign` vs `both`?', back: '`foreign`: all channels except the radio\'s operating channel. `both`: foreign plus the home channel. `disable` is the default.' },
  { id: 'd3-f008', topic: '3.1', front: 'Radio `mode` values?', back: '`ap` (default), `monitor` (Dedicated Monitor), `sniffer`, `sam` (Service Assurance client), `disabled`.' },
  { id: 'd3-f009', topic: '3.1', front: 'What does `ddscan` do on FortiAP F-series profiles?', back: 'Uses one radio for dedicated full-band scanning. Disabling it makes the WIDS profile available on radios 1 and 2 for background scanning.' },
  { id: 'd3-f010', topic: '3.1', front: 'How does rogue suppression work?', back: 'A monitor radio sends deauthentication frames to the rogue\'s clients (as the rogue) and to the rogue (as its clients).' },
  { id: 'd3-f011', topic: '3.1', front: 'Suppression prerequisites?', back: 'On-wire rogue scanning enabled, the suppressing radio in **Dedicated Monitor** mode, and confirmation that local law allows it.' },
  { id: 'd3-f012', topic: '3.1', front: 'CLI to mark a BSSID suppressed?', back: '`config wireless-controller ap-status` → `edit <id>` → `set bssid`, `set ssid`, `set status suppressed` (rogue / accepted / suppressed).' },
  { id: 'd3-f013', topic: '3.1', front: 'Fake SSID vs offending SSID?', back: 'Fake: an SSID defined on this FortiGate broadcast by an unmanaged AP. Offending: matches a case-insensitive `ssid-pattern` you define. Both under `config wireless-controller setting`.' },
  { id: 'd3-f014', topic: '3.1', front: 'Default `fake-ssid-action`?', back: '`log`. Add `suppress` (`set fake-ssid-action log suppress`) to attack it too. `phishing-ssid-detect` defaults to enable.' },
  { id: 'd3-f015', topic: '3.1', front: '`wlac -c ap-rogue` code letters?', back: 'C configured (G accept, B rogue, S suppress, U unconfigured), M managed (V vdom, C AC, N unmanaged), W on wire (Y/N), P phishing (F fake, O offending, N no).' },
  { id: 'd3-f016', topic: '3.3', front: 'FortiAIOps wireless SLAs?', back: 'Throughput, Coverage, Roaming, Time to Connect, Connection Failure, AP Health and Uptime, WIDS.' },
  { id: 'd3-f017', topic: '3.1', front: 'What does WIDS do when it detects an attack?', back: 'Logs it. All detections are off by default and are applied per radio with `set wids-profile`.' },
  { id: 'd3-f018', topic: '3.1', front: '`deauth-unknown-src-thresh`?', back: 'WIDS profile limit on the rate of DoS-mitigation deauthentication to unknown clients, per second (default 10, 0 = no limit).' },
  { id: 'd3-f019', topic: '3.3', front: 'Adding a FortiGate to FortiAIOps?', back: 'Inventory > Managed FortiGates > Add: IP/FQDN (must match the FortiGate certificate SAN), admin credentials, ADOM, HTTPS port 443. Then forward logs (syslogd or FortiAnalyzer).' },
  { id: 'd3-f020', topic: '3.2', front: 'Client health thresholds (signal, SNR, band)?', back: 'Signal: Good > -56 dBm, Fair to -75, Poor below. SNR: Good > 39 dB, Fair 20–39, Poor < 20. Band: 5 GHz Good, 2.4 GHz Fair. All must be Good for Good.' },
  { id: 'd3-f021', topic: '3.2', front: 'Quarantine vs Disassociate a WiFi client?', back: 'Quarantine blocks the host. Disassociate only drops the current association; the client can reconnect.' },
  { id: 'd3-f022', topic: '3.2', front: 'FortiAP REST API: read CPU and memory?', back: '`GET https://<FAP-IP>/api/v1/sys-perf` after `POST /logincheck`.' },
  { id: 'd3-f023', topic: '3.2', front: 'FortiAP REST API calls that use POST?', back: '`/logincheck`, `/logout`, `/api/v1/cfg-set`, `/api/v1/reboot`. Reads (`sys-status`, `cfg-get`, `wtp-cfg`, `radio-cfg`, `vap-cfg`) use GET.' },
  { id: 'd3-f024', topic: '3.2', front: '802.11k / 802.11v / 802.11r in one line each?', back: 'k: neighbor reports. v: BSS transition management (AP suggests a better AP). r: Fast BSS Transition (fast key derivation on roam).' },
  { id: 'd3-f025', topic: '3.2', front: 'FortiOS SSID roaming defaults?', back: '`80211k` enable, `80211v` enable, `okc` enable, `fast-bss-transition` disable (`ft-mobility-domain` 1000).' },
  { id: 'd3-f026', topic: '3.2', front: 'L3 roaming rehome timer?', back: '`config wireless-controller timers` → `client-idle-rehome-timeout` (default 20 s). After it, the roamed client gets a local DHCP address.' },
  { id: 'd3-f027', topic: '3.2', front: 'Frequency handoff vs AP handoff?', back: 'Frequency: AP ignores 2.4 GHz joins from dual-band clients with good 5 GHz signal. AP: an AP over `handoff-sta-thresh` ignores new clients so the least busy nearby AP answers. The guide says load balancing is not applied to roaming clients.' },
  { id: 'd3-f028', topic: '3.3', front: 'AI-ARRP radio settings?', back: '`set darrp enable` + `set ai-darrp-support enable` (default disable). Only `ai-darrp-support`: FortiAIOps reads via GET. Both: it changes channels via POST. FortiOS 7.6.5 / FortiAP 7.6.3.' },
];
